/* ============================================================================
   GlbTOKEN i18n — SINGLE translation file (industry-standard layout)
   ============================================================================
   One dictionary object:  I18N[key] = { "zh-CN": …, ru: …, ja: …, de: … }
     · Text keys  = exact English copy   → auto-matched against DOM text nodes
     · Short keys = kebab-case ids       → used via data-i18n="key" attributes
     · hero-* keys keep an en: field     → JS fallback for rotating hero copy
   English (en) is the key itself — regular entries store no en: field.

   Public API
     · t(key, fallback)      — current-language string for JS rendering
     · switchLanguage(lang)  — persist to localStorage('gt_lang') + reload
     · translatePage()       — apply the dictionary to the current DOM

   Language: localStorage 'gt_lang' ∈ {en, zh-CN, ru, ja, de}  (default en)
   Load order: translations.js BEFORE shared.js / ui.js / filters.js
   ============================================================================ */

var I18N = {};                                    // THE dictionary (data below)

var curLang = localStorage.getItem('gt_lang') || 'en';

function t(key, fallback) {
  if (I18N[key] && I18N[key][curLang]) return I18N[key][curLang];
  return (fallback !== undefined) ? fallback : key;
}

function switchLanguage(lang) {
  curLang = lang;
  localStorage.setItem('gt_lang', lang);
  location.reload();                              // full re-render in new language
}

function translatePage() {
  // 1) data-i18n attributes → HTML-safe replacement (keeps child elements)
  document.querySelectorAll('[data-i18n]').forEach(function (el) {
    var key = el.getAttribute('data-i18n');
    if (I18N[key] && I18N[key][curLang]) el.innerHTML = I18N[key][curLang];
  });
  // 2) visible text nodes → exact English match
  var walker = document.createTreeWalker(document.body, 4, null, false);
  var nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (var i = 0; i < nodes.length; i++) {
    var n = nodes[i];
    if (!n.parentNode) continue;
    if (n.parentNode.closest && n.parentNode.closest('.notranslate,[translate="no"],script,style,svg,code,pre,option,.lang-selector,.lang-menu,.lang-option,.nav-logo,.logo-glb,.logo-token,.trust-badge,.star,.tm-dot,.tm-arrow,.copying,select,input,textarea,.lang-btn,.lang-btn-mobile')) continue;
    var text = n.textContent.trim();
    if (!text || text.length < 2 || text.length > 2000) continue;
    if (I18N[text] && I18N[text][curLang]) {
      n.textContent = I18N[text][curLang];
    }
  }
}

function updateLangUI(lang) {
  document.querySelectorAll('.lang-option').forEach(function (el) {
    el.classList.toggle('active', el.getAttribute('data-lang') === lang);
  });
  var lbl = document.getElementById('currentLangLabel');
  if (lbl) lbl.textContent = lang === 'zh-CN' ? '中文' : lang === 'en' ? 'EN' : lang === 'ru' ? 'RU' : lang === 'ja' ? '日' : 'DE';
  var lm = document.getElementById('langMenu');
  if (lm) lm.classList.remove('open');
}

