I18N["One balance for 100+ models across 56 providers. Switch between GPT, Claude, Llama, Gemini instantly."] = {"zh-CN": "一个余额即可使用56家提供商的100多个模型。在GPT、Claude、Llama、Gemini之间即时切换。", ru: "Один баланс для 100+ моделей от 56 провайдеров. Мгновенно переключайтесь между GPT, Claude, Llama, Gemini.", ja: "1つの残高で56のプロバイダーにわたる100以上のモデルを利用。GPT、Claude、Llama、Geminiを瞬時に切り替え。", de: "Ein Guthaben für 100+ Modelle von 56 Anbietern. Wechseln Sie sofort zwischen GPT, Claude, Llama, Gemini."};
I18N["Sign up with email, Google, or GitHub. No credit card needed."] = {"zh-CN": "使用邮箱、Google或GitHub注册。无需信用卡。", ru: "Регистрируйтесь по email, через Google или GitHub. Кредитная карта не требуется.", ja: "メール、Google、またはGitHubでサインアップ。クレジットカード不要。", de: "Anmeldung per E-Mail, Google oder GitHub. Keine Kreditkarte erforderlich."};
I18N["No hidden fees — transparent pricing"] = {"zh-CN": "无隐藏费用——透明定价", ru: "Без скрытых платежей — прозрачные цены", ja: "隠れ費用なし — 透明な料金設定", de: "Keine versteckten Gebühren — transparente Preise"};
I18N["Instant top-up — tokens in seconds"] = {"zh-CN": "即时充值——秒到账", ru: "Мгновенное пополнение — токены за секунды", ja: "即時チャージ — トークンが数秒で反映", de: "Sofortige Aufladung — Token in Sekunden"};
I18N["Usage-based pricing — only pay for what you use"] = {"zh-CN": "按使用量计费——只为使用部分付费", ru: "Оплата по использованию — платите только за то, что используете", ja: "使用量ベースの料金 — 使った分だけ支払い", de: "Nutzungsbasierte Preisgestaltung — nur für das bezahlen, was Sie nutzen"};
I18N["OpenAI-compatible endpoint. One API key for 100+ models. Integrate in minutes."] = {"zh-CN": "OpenAI兼容端点。一个API密钥可用于100多个模型。几分钟内完成集成。", ru: "Совместимая с OpenAI конечная точка. Один API-ключ для 100+ моделей. Интеграция за минуты.", ja: "OpenAI互換のエンドポイント。1つのAPIキーで100以上のモデル。数分で統合。", de: "OpenAI-kompatibler Endpunkt. Ein API-Schlüssel für 100+ Modelle. Integration in Minuten."};
