I18N["End-to-End Encryption for Sensitive Workloads"] = {"zh-CN": "敏感工作负载的端到端加密","ru": "Сквозное шифрование для чувствительных нагрузок","ja": "機密ワークロードのエンドツーエンド暗号化","de": "Ende-zu-Ende-Verschlüsselung für sensible Arbeitslasten",};
I18N["Data Isolation Architecture"] = {"zh-CN": "数据隔离架构","ru": "Архитектура изоляции данных","ja": "データ分離アーキテクチャ","de": "Datenisolation-Architektur",};
I18N["Database-Level Isolation."] = {"zh-CN": "数据库级隔离。","ru": "Изоляция на уровне базы данных.","ja": "データベースレベルの分離。","de": "Isolation auf Datenbankebene.",};
I18N["Application-Level Isolation."] = {"zh-CN": "应用级隔离。","ru": "Изоляция на уровне приложения.","ja": "アプリケーションレベルの分離。","de": "Isolation auf Anwendungsebene.",};
I18N["Infrastructure-Level Isolation."] = {"zh-CN": "基础设施级隔离。","ru": "Изоляция на уровне инфраструктуры.","ja": "インフラレベルの分離。","de": "Isolation auf Infrastrukturebene.",};
I18N["For Enterprise customers, we offer dedicated inference endpoints on isolated compute resources. No data crosses between customer environments at the infrastructure layer."] = {"zh-CN": "对于企业客户，我们在隔离的计算资源上提供专用推理端点。在基础设施层，客户环境之间没有数据交叉。","ru": "Для корпоративных клиентов мы предлагаем выделенные inference-endpoint'ы на изолированных вычислительных ресурсах. На уровне инфраструктуры данные не пересекаются между средами клиентов.","ja": "エンタープライズのお客様には、分離されたコンピュートリソース上の専用推論エンドポイントを提供。インフラ層では顧客環境間でデータが交差することはありません。","de": "Für Enterprise-Kunden bieten wir dedizierte Inferenz-Endpunkte auf isolierten Rechenressourcen. Auf Infrastrukturebene überqueren keine Daten die Umgebungen der Kunden.",};
I18N["Access Control & Audit Logging"] = {"zh-CN": "访问控制与审计日志","ru": "Контроль доступа и журналы аудита","ja": "アクセス制御と監査ログ","de": "Zugriffskontrolle und Audit-Protokollierung",};
I18N["Role-Based Access Control (RBAC)."] = {"zh-CN": "基于角色的访问控制（RBAC）。","ru": "Контроль доступа на основе ролей (RBAC).","ja": "ロールベースのアクセス制御（RBAC）。","de": "Rollenzugriffskontrolle (RBAC).",};
I18N["Vulnerability Management & Penetration Testing"] = {"zh-CN": "漏洞管理与渗透测试","ru": "Управление уязвимостями и пентесты","ja": "脆弱性管理とペネトレーションテスト","de": "Schwachstellenmanagement & Penetrationstests",};
I18N["Automated vulnerability scanning"] = {"zh-CN": "自动化漏洞扫描","ru": "Автоматическое сканирование уязвимостей","ja": "自動脆弱性スキャン","de": "Automatisiertes Schwachstellen-Scanning",};
I18N["of all infrastructure and dependencies — every 6 hours."] = {"zh-CN": "对所有基础设施和依赖项 —— 每 6 小时一次。","ru": "всей инфраструктуры и зависимостей — каждые 6 часов.","ja": "すべてのインフラと依存関係を対象に — 6時間ごと。","de": "der gesamten Infrastruktur und Abhängigkeiten — alle 6 Stunden.",};
I18N["Annual third-party penetration testing"] = {"zh-CN": "年度第三方渗透测试","ru": "Ежегодное стороннее тестирование на проникновение","ja": "年次の第三者ペネトレーションテスト","de": "Jährliche externe Penetrationstests",};
I18N["by a licensed PCI-qualified assessor. The most recent pentest found zero critical or high-severity findings."] = {"zh-CN": "由持牌的 PCI 合格评估员执行。最近一次渗透测试发现零个严重或高危问题。","ru": "лицензированным оценщиком PCI. Последний пентест не выявил ни одной критической или высокосерьезной проблемы.","ja": "ライセンスを持つPCI認定評価者による実施。直近のペネトレーションテストでは重大・高重要度の問題はゼロでした。","de": "durch einen lizenzierten PCI-qualifizierten Prüfer. Der jüngste Pentest ergab keine kritischen oder hochschwerwiegenden Befunde.",};
I18N["A responsible disclosure program"] = {"zh-CN": "负责任的披露计划","ru": "Программа ответственного раскрытия","ja": "責任ある情報開示プログラム","de": "Ein Programm zur verantwortungsvollen Offenlegung",};
I18N["with a published security policy and bug bounty. We commit to a 72-hour initial response time for all verified security reports."] = {"zh-CN": "配有公开的安全策略和漏洞赏金。我们承诺对所有已验证的安全报告在 72 小时内做出首次响应。","ru": "с опубликованной политикой безопасности и баг-баунти. Мы обязуемся отвечать в течение 72 часов на все подтвержденные отчеты о безопасности.","ja": "公開されたセキュリティポリシーとバグバウンティ付き。検証済みのセキュリティレポートには72時間以内の初期対応を約束します。","de": "mit veröffentlichter Sicherheitsrichtlinie und Bug-Bounty. Wir verpflichten uns zu einer ersten Reaktionszeit von 72 Stunden für alle verifizierten Sicherheitsmeldungen.",};
I18N["Dependency monitoring"] = {"zh-CN": "依赖监控","ru": "Мониторинг зависимостей","ja": "依存関係の監視","de": "Abhängigkeitsüberwachung",};
I18N["with automated patch deployment for critical CVEs — 24-hour SLA for Critical, 72-hour for High."] = {"zh-CN": "对关键 CVE 自动部署补丁 —— 严重问题 24 小时 SLA，高危问题 72 小时。","ru": "с автоматическим развертыванием патчей для критических CVE — SLA 24 часа для критических, 72 часа для высоких.","ja": "重要CVEへの自動パッチ適用 — 重大は24時間SLA、高は72時間。","de": "mit automatischer Patch-Bereitstellung für kritische CVEs — 24-Stunden-SLA für Kritisch, 72 Stunden für Hoch.",};
