I18N["rotate-keys"] = {"zh-CN": '<strong style="color:var(--text)">\u5b9a\u671f\u8f6e\u6362\u5bc6\u94a5</strong> \u2014 \u4ece\u63a7\u5236\u53f0\u751f\u6210\u65b0\u7684 API \u5bc6\u94a5\u5e76\u64a4\u9500\u65e7\u7684\u5bc6\u94a5\u3002', ru: '<strong style="color:var(--text)">\u0420\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u043e \u043c\u0435\u043d\u044f\u0439\u0442\u0435 \u043a\u043b\u044e\u0447\u0438</strong> \u2014 \u0421\u043e\u0437\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043d\u043e\u0432\u044b\u0435 API-\u043a\u043b\u044e\u0447\u0438 \u0432 \u043f\u0430\u043d\u0435\u043b\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0438 \u043e\u0442\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0441\u0442\u0430\u0440\u044b\u0435.', ja: '<strong style="color:var(--text)">\u5b9a\u671f\u7684\u306b\u30ad\u30fc\u3092\u30ed\u30fc\u30c6\u30fc\u30b7\u30e7\u30f3</strong> \u2014 \u30c0\u30c3\u30b7\u30e5\u30dc\u30fc\u30c9\u304b\u3089\u65b0\u3057\u3044API\u30ad\u30fc\u3092\u751f\u6210\u3057\u3001\u53e4\u3044\u30ad\u30fc\u3092\u7121\u52b9\u5316\u3057\u307e\u3059\u3002', de: '<strong style="color:var(--text)">Schl\u00fcssel regelm\u00e4\u00dfig rotieren</strong> \u2014 Erstellen Sie neue API-Schl\u00fcssel \u00fcber Ihr Dashboard und widerrufen Sie alte.'};
I18N["separate-keys"] = {"zh-CN": '<strong style="color:var(--text)">\u6bcf\u4e2a\u9879\u76ee\u4f7f\u7528\u72ec\u7acb\u5bc6\u94a5</strong> \u2014 \u6709\u52a9\u4e8e\u8ddf\u8e2a\u4f7f\u7528\u60c5\u51b5\u5e76\u9650\u5236\u5f71\u54cd\u8303\u56f4\u3002', ru: '<strong style="color:var(--text)">\u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0439\u0442\u0435 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u043a\u043b\u044e\u0447\u0438 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430</strong> \u2014 \u041f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u043e\u0442\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u0442\u044c \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0442\u044c \u0440\u0430\u0434\u0438\u0443\u0441 \u043f\u043e\u0440\u0430\u0436\u0435\u043d\u0438\u044f.', ja: '<strong style="color:var(--text)">\u30d7\u30ed\u30b8\u30a7\u30af\u30c8\u3054\u3068\u306b\u500b\u5225\u306e\u30ad\u30fc\u3092\u4f7f\u7528</strong> \u2014 \u4f7f\u7528\u72b6\u6cc1\u306e\u8ffd\u8de1\u3068\u30d6\u30e9\u30b9\u30c8\u30fb\u30e9\u30b8\u30a6\u30b9\u306e\u5236\u9650\u306b\u5f79\u7acb\u3061\u307e\u3059\u3002', de: '<strong style="color:var(--text)">Separate Schl\u00fcssel pro Projekt verwenden</strong> \u2014 Hilft bei der Verfolgung der Nutzung und begrenzt die Auswirkungen.'};
I18N["set-max-tokens"] = {"zh-CN": '<strong style="color:var(--text)">\u8bbe\u7f6e\u6700\u5927\u4ee3\u5e01\u6570</strong> \u2014 \u59cb\u7ec8\u8bbe\u7f6e <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">max_tokens</code> \u4ee5\u63a7\u5236\u6210\u672c\u3002', ru: '<strong style="color:var(--text)">\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435 max tokens</strong> \u2014 \u0412\u0441\u0435\u0433\u0434\u0430 \u0443\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0439\u0442\u0435 <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">max_tokens</code> \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432.', ja: '<strong style="color:var(--text)">\u6700\u5927\u30c8\u30fc\u30af\u30f3\u3092\u8a2d\u5b9a</strong> \u2014 \u30b3\u30b9\u30c8\u3092\u5236\u5fa1\u3059\u308b\u305f\u3081\u306b <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">max_tokens</code> \u3092\u5e38\u306b\u8a2d\u5b9a\u3057\u3066\u304f\u3060\u3055\u3044\u3002', de: '<strong style="color:var(--text)">Max. Token festlegen</strong> \u2014 Setzen Sie immer <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">max_tokens</code>, um die Kosten zu kontrollieren.'};
I18N["monitor-usage"] = {"zh-CN": '<strong style="color:var(--text)">\u76d1\u63a7\u4f7f\u7528\u60c5\u51b5</strong> \u2014 \u5728\u63a7\u5236\u53f0\u67e5\u770b\u5b9e\u65f6\u4ee3\u5e01\u6d88\u8017\u3002', ru: '<strong style="color:var(--text)">\u041e\u0442\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435</strong> \u2014 \u041f\u0440\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u043f\u043e\u0442\u0440\u0435\u0431\u043b\u0435\u043d\u0438\u0435 \u0442\u043e\u043a\u0435\u043d\u043e\u0432 \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0432 \u043f\u0430\u043d\u0435\u043b\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f.', ja: '<strong style="color:var(--text)">\u4f7f\u7528\u72b6\u6cc1\u3092\u76e3\u8996</strong> \u2014 \u30c0\u30c3\u30b7\u30e5\u30dc\u30fc\u30c9\u3067\u30ea\u30a2\u30eb\u30bf\u30a4\u30e0\u306e\u30c8\u30fc\u30af\u30f3\u6d88\u8cbb\u3092\u78ba\u8a8d\u3057\u3066\u304f\u3060\u3055\u3044\u3002', de: '<strong style="color:var(--text)">Nutzung \u00fcberwachen</strong> \u2014 \u00dcberpr\u00fcfen Sie Ihren Echtzeit-Token-Verbrauch im Dashboard.'};
I18N["handle-402"] = {"zh-CN": '<strong style="color:var(--text)">\u5904\u7406 402 \u9519\u8bef</strong> \u2014 \u5728\u4f59\u989d\u7528\u5c3d\u524d\u5145\u503c\uff0c\u907f\u514d\u670d\u52a1\u4e2d\u65ad\u3002', ru: '<strong style="color:var(--text)">\u041e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0439\u0442\u0435 \u043e\u0448\u0438\u0431\u043a\u0438 402</strong> \u2014 \u041f\u043e\u043f\u043e\u043b\u043d\u044f\u0439\u0442\u0435 \u0431\u0430\u043b\u0430\u043d\u0441 \u0434\u043e \u0435\u0433\u043e \u0438\u0441\u0442\u043e\u0449\u0435\u043d\u0438\u044f, \u0447\u0442\u043e\u0431\u044b \u0438\u0437\u0431\u0435\u0436\u0430\u0442\u044c \u043f\u0435\u0440\u0435\u0440\u044b\u0432\u0430 \u0432 \u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u043d\u0438\u0438.', ja: '<strong style="color:var(--text)">402 \u30a8\u30e9\u30fc\u3092\u51e6\u7406</strong> \u2014 \u6b8b\u9ad8\u304c\u306a\u304f\u306a\u308b\u524d\u306b\u30c1\u30e3\u30fc\u30b8\u3057\u3066\u3001\u30b5\u30fc\u30d3\u30b9\u4e2d\u65ad\u3092\u907f\u3051\u3066\u304f\u3060\u3055\u3044\u3002', de: '<strong style="color:var(--text)">402-Fehler behandeln</strong> \u2014 Laden Sie Ihr Guthaben auf, bevor es aufgebraucht ist, um Serviceunterbrechungen zu vermeiden.'};
I18N["first-key"] = {"zh-CN": '\u6ce8\u518c\u540e\uff0c\u4ece <a href="dashboard.html" style="color:var(--primary)">\u63a7\u5236\u53f0</a> \u751f\u6210\u60a8\u7684\u7b2c\u4e00\u4e2a API \u5bc6\u94a5\u3002', ru: '\u0421\u043e\u0437\u0434\u0430\u0439\u0442\u0435 \u0441\u0432\u043e\u0439 \u043f\u0435\u0440\u0432\u044b\u0439 API-\u043a\u043b\u044e\u0447 \u0432 <a href="dashboard.html" style="color:var(--primary)">\u043f\u0430\u043d\u0435\u043b\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f</a> \u043f\u043e\u0441\u043b\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438.', ja: '\u30b5\u30a4\u30f3\u30a2\u30c3\u30d7\u5f8c\u3001<a href="dashboard.html" style="color:var(--primary)">\u30c0\u30c3\u30b7\u30e5\u30dc\u30fc\u30c9</a>\u304b\u3089\u6700\u521d\u306eAPI\u30ad\u30fc\u3092\u751f\u6210\u3057\u3066\u304f\u3060\u3055\u3044\u3002', de: 'Generieren Sie Ihren ersten API-Schl\u00fcssel \u00fcber das <a href="dashboard.html" style="color:var(--primary)">Dashboard</a> nach der Anmeldung.'};
I18N["browse-models"] = {"zh-CN": '\u6216\u5728 <a href="models.html" style="color:var(--primary)">\u6a21\u578b</a> \u9875\u9762\u4e0a\u6d4f\u89c8\u6240\u6709\u6a21\u578b\u3002', ru: '\u0418\u043b\u0438 \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u0432\u0441\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 \u043d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 <a href="models.html" style="color:var(--primary)">\u041c\u043e\u0434\u0435\u043b\u0438</a>.', ja: '\u307e\u305f\u306f <a href="models.html" style="color:var(--primary)">\u30e2\u30c7\u30eb</a> \u30da\u30fc\u30b8\u3067\u3059\u3079\u3066\u306e\u30e2\u30c7\u30eb\u3092\u53c2\u7167\u3057\u3066\u304f\u3060\u3055\u3044\u3002', de: 'Oder durchsuchen Sie alle Modelle auf der <a href="models.html" style="color:var(--primary)">Modelle</a>-Seite.'};
I18N["full-pricing-ref"] = {"zh-CN": '\u5b8c\u6574\u5b9a\u4ef7\uff1a<a href="pricing.html" style="color:var(--primary)">\u4ef7\u683c\u9875\u9762</a> | 1,000 GT = $1 USD', ru: '\u041f\u043e\u043b\u043d\u044b\u0435 \u0446\u0435\u043d\u044b: <a href="pricing.html" style="color:var(--primary)">\u0421\u0442\u0440\u0430\u043d\u0438\u0446\u0430 \u0446\u0435\u043d</a> | 1,000 GT = $1 USD', ja: '\u5b8c\u5168\u306a\u6599\u91d1\uff1a<a href="pricing.html" style="color:var(--primary)">\u6599\u91d1\u30da\u30fc\u30b8</a> | 1,000 GT = $1 USD', de: 'Vollst\u00e4ndige Preise: <a href="pricing.html" style="color:var(--primary)">Preisseite</a> | 1,000 GT = $1 USD'};
I18N["api-costs"] = {"zh-CN": '\u6bcf\u6b21 API \u8c03\u7528\u6839\u636e\u4f7f\u7528\u7684\u6a21\u578b\u6d88\u8017 GlbTOKEN\u3002\u4ef7\u683c\u56e0\u6a21\u578b\u80fd\u529b\u800c\u5f02\uff1a', ru: '\u041a\u0430\u0436\u0434\u044b\u0439 API-\u0437\u0430\u043f\u0440\u043e\u0441 \u0440\u0430\u0441\u0445\u043e\u0434\u0443\u0435\u0442 GlbTOKEN \u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u043c\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438. \u0426\u0435\u043d\u044b \u0437\u0430\u0432\u0438\u0441\u044f\u0442 \u043e\u0442 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0435\u0439 \u043c\u043e\u0434\u0435\u043b\u0438:', ja: '\u5404API\u547c\u3073\u51fa\u3057\u306f\u4f7f\u7528\u3059\u308b\u30e2\u30c7\u30eb\u306b\u57fa\u3065\u3044\u3066GlbTOKEN\u3092\u6d88\u8cbb\u3057\u307e\u3059\u3002\u4fa1\u683c\u306f\u30e2\u30c7\u30eb\u306e\u6a5f\u80fd\u306b\u3088\u3063\u3066\u7570\u306a\u308a\u307e\u3059\uff1a', de: 'Jeder API-Aufruf verbraucht GlbTOKEN basierend auf dem verwendeten Modell. Die Preise variieren je nach Modellleistung:'};
I18N["unused-tokens"] = {"zh-CN": '<strong>\u672a\u4f7f\u7528\u4ee3\u5e01</strong><br>\u5982\u679c\u60a8\u7684\u8d26\u6237\u5904\u4e8e\u6d3b\u8dc3\u72b6\u6001\u4e14\u4ee3\u5e01\u672a\u88ab\u4f7f\u7528\uff0c\u8bf7\u8054\u7cfb <a href="mailto:support@glbtoken.com" style="color:var(--primary)">support@glbtoken.com</a> \u8fdb\u884c\u4e2a\u6848\u5ba1\u6838\u3002', ru: '<strong>\u041d\u0435\u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0442\u043e\u043a\u0435\u043d\u044b</strong><br>\u0415\u0441\u043b\u0438 \u0432\u0430\u0448 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0430\u043a\u0442\u0438\u0432\u0435\u043d, \u0430 \u0442\u043e\u043a\u0435\u043d\u044b \u043d\u0435 \u0431\u044b\u043b\u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u044b, \u0441\u0432\u044f\u0436\u0438\u0442\u0435\u0441\u044c \u0441 \u043d\u0430\u043c\u0438 \u043f\u043e <a href="mailto:support@glbtoken.com" style="color:var(--primary)">support@glbtoken.com</a> \u0434\u043b\u044f \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u044f.', ja: '<strong>\u672a\u4f7f\u7528\u30c8\u30fc\u30af\u30f3</strong><br>\u30a2\u30ab\u30a6\u30f3\u30c8\u304c\u6709\u52b9\u3067\u30c8\u30fc\u30af\u30f3\u304c\u4f7f\u7528\u3055\u308c\u3066\u3044\u306a\u3044\u5834\u5408\u306f\u3001<a href="mailto:support@glbtoken.com" style="color:var(--primary)">support@glbtoken.com</a> \u307e\u3067\u30b1\u30fc\u30b9\u30d0\u30a4\u30b1\u30fc\u30b9\u3067\u306e\u5be9\u67fb\u306b\u3064\u3044\u3066\u304a\u554f\u3044\u5408\u308f\u305b\u304f\u3060\u3055\u3044\u3002', de: '<strong>Ungenutzte Token</strong><br>Wenn Ihr Konto aktiv ist und Token nicht verwendet wurden, kontaktieren Sie uns bitte unter <a href="mailto:support@glbtoken.com" style="color:var(--primary)">support@glbtoken.com</a> f\u00fcr eine Einzelfallpr\u00fcfung.'};

I18N["sdk-compat"] = {"zh-CN": '此端点与 OpenAI SDK 完全兼容。只需更改 <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">base_url</code> 和您的 <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">api_key</code> 即可。', ru: 'Эта конечная точка полностью совместима с OpenAI SDK. Просто измените <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">base_url</code> и ваш <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">api_key</code>.', ja: 'このエンドポイントはOpenAI SDKと完全互換です。<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">base_url</code> とあなたの <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">api_key</code> を変更するだけです。', de: 'Dieser Endpunkt ist vollständig mit dem OpenAI SDK kompatibel. Ändern Sie einfach die <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">base_url</code> und Ihren <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px;font-size:0.85rem">api_key</code>.'};
I18N["chat-compat"] = {"zh-CN": '发送聊天补全请求（兼容 OpenAI）：', ru: 'Отправьте запрос на завершение чата (совместимый с OpenAI):', ja: 'チャット補完リクエストを送信（OpenAI互換）：', de: 'Senden Sie eine Chat-Completion-Anfrage (OpenAI-kompatibel):'};
I18N["params-supported"] = {"zh-CN": '支持 OpenAI API 的所有参数：<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">stream</code>、<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">frequency_penalty</code>、<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">top_p</code> 等。', ru: 'Поддерживаются все параметры OpenAI API: <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">stream</code>, <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">frequency_penalty</code>, <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">top_p</code> и др.', ja: 'OpenAI APIのすべてのパラメータをサポート：<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">stream</code>、<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">frequency_penalty</code>、<code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">top_p</code> など。', de: 'Alle Parameter der OpenAI API werden unterstützt: <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">stream</code>, <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">frequency_penalty</code>, <code translate="no" style="background:var(--bg-alt);padding:0.15rem 0.4rem;border-radius:4px">top_p</code>, etc.'};
I18N["sse-streaming"] = {"zh-CN": '完全支持 Server-Sent Events (SSE) 流式传输：', ru: 'Потоковая передача Server-Sent Events (SSE) полностью поддерживается:', ja: 'Server-Sent Events (SSE) ストリーミングを完全サポート：', de: 'Server-Sent Events (SSE)-Streaming wird vollständig unterstützt:'};


