I18N["footer-tagline"] = {"zh-CN": "AI 全球通证。一个余额，100+ 模型，56 家供应商。按需付费。", ru: "Глобальный токен для ИИ. Один баланс, 100+ моделей, 56 провайдеров. Оплата по мере использования.", ja: "AIのためのグローバルトークン。1つの残高、100以上のモデル、56のプロバイダー。従量課金制。", de: "Globaler Token für KI. Ein Guthaben, 100+ Modelle, 56 Anbieter. Pay-as-you-go."};
